with a as(select * from public.authors where open_library_id=any(array['OL1392395A','OL26467A']::text[])),w as(select * from public.works where open_library_id=any(array['OL5725956W','OL28623W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9780613750356','9798674057338','9789047500445','9789063280918']::text[]) or open_library_edition_id=any(array['OL10954175M','OL38132499M','OL27098593M','OL47095894M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987106001 and 987106999),'editions',(select count(*) from public.editions where id between 987206001 and 987206999),'authors',(select count(*) from public.authors where id between 987306001 and 987306999))) as preflight;
